#include <genesis.h>
#include "game_floor.h"
#include "game_room.h"
#include "game_player.h"
#include "gfx.h"

#ifdef DEBUG_SCRIPT
#include "script.h"     // generated by tools/replay.ps1 (found through -Itools)
#endif

// Room: D-pad run, C jump, B slash, DOWN crouch, DOWN + C drop, START = floor map.
// Map:  START back, A run/stop the Void, B show secrets, C new floor.

enum { MODE_ROOM, MODE_MAP };

#define MAP_X 2
#define MAP_Y 4

static Floor floor;
static Room room;
static Player player;
static u8 mode = MODE_ROOM;
static u8 depth = 1;
static bool showSecrets = FALSE;
static bool voidRunning = FALSE;
static u16 radius;          // Void radius, same units as floor_voidDist2()
static u16 voidFrames;

// ---------------------------------------------------------------- floor map

static const char LETTER[] = { ' ', '.', 'S', 'B', 'U', '$', '?', '!' };

static u16 startRadius(void)
{
    u16 maxD2 = 0;
    for (u8 y = 0; y < FLOOR_H; y++)
        for (u8 x = 0; x < FLOOR_W; x++)
            if (floor.type[y][x] != ROOM_NONE)
            {
                u16 d2 = floor_voidDist2(&floor, x, y);
                if (d2 > maxD2) maxD2 = d2;
            }
    u16 r = 0;
    while (r * r <= maxD2) r++;
    return r;
}

static void drawCell(u8 x, u8 y)
{
    u8 t = floor.type[y][x];
    u8 secret = t == ROOM_SECRET || t == ROOM_SUPER_SECRET;
    if (t == ROOM_NONE || (secret && !showSecrets)) return;

    u16 px = MAP_X + x * 4, py = MAP_Y + y * 3;
    u16 pal = PAL0;
    if (t == ROOM_BOSS) pal = PAL1;
    else if (t >= ROOM_UPGRADE) pal = PAL2;
    if (!secret && floor_voidDist2(&floor, x, y) > radius * radius) pal = PAL3;

    char cell[4] = { '[', LETTER[t], ']', 0 };
    VDP_setTextPalette(pal);
    VDP_drawText(cell, px, py);

    // Doors are drawn by the room on their left/top side only.
    u8 doors = floor.doors[y][x], hidden = showSecrets ? floor.hidden[y][x] : 0;
    VDP_setTextPalette(PAL0);
    if (doors & DOOR_RIGHT) VDP_drawText("-", px + 3, py);
    if (doors & DOOR_DOWN) VDP_drawText("|", px + 1, py + 1);
    VDP_setTextPalette(PAL2);
    if (hidden & DOOR_RIGHT) VDP_drawText("=", px + 3, py);
    if (hidden & DOOR_DOWN) VDP_drawText(":", px + 1, py + 1);
}

static void drawMapStatus(void)
{
    char line[41];
    VDP_setTextPalette(PAL0);
    sprintf(line, "GRAINE %04X  ETAGE %u  SALLES %u   ", floor.seed, depth, floor.roomCount);
    VDP_drawText(line, 2, 2);
    sprintf(line, "NEANT R=%3u %s   ", radius, voidRunning ? "AVANCE" : "ARRET ");
    VDP_drawText(line, 2, 27);
}

static void drawMap(void)
{
    VDP_clearPlane(BG_A, TRUE);
    VDP_clearPlane(BG_B, TRUE);
    VDP_setTextPalette(PAL0);
    VDP_drawText("CARTE  START retour", 2, 0);
    VDP_drawText("A neant  B secrets  C nouvel etage", 2, 1);
    for (u8 y = 0; y < FLOOR_H; y++)
        for (u8 x = 0; x < FLOOR_W; x++) drawCell(x, y);
    drawMapStatus();
}

static void newFloor(u16 seed)
{
    floor_generate(&floor, seed, depth);
    radius = startRadius();
    voidRunning = FALSE;
}

static void updateMap(u16 pressed)
{
    if (pressed & BUTTON_C)
    {
        depth = depth % 6 + 1;
        newFloor(random() ^ vtimer);
        drawMap();
    }
    if (pressed & BUTTON_B)
    {
        showSecrets = !showSecrets;
        drawMap();
    }
    if (pressed & BUTTON_A)
    {
        if (radius == 0) radius = startRadius();
        voidRunning = !voidRunning;
        drawMapStatus();
    }
    // The Void shrinks by one unit per second, whatever the region.
    if (voidRunning && ++voidFrames >= (IS_PAL_SYSTEM ? 50 : 60))
    {
        voidFrames = 0;
        if (radius) radius--;
        if (!radius) voidRunning = FALSE;
        drawMap();
    }
}

// ---------------------------------------------------------------- room

static void drawRoom(void)
{
    for (u8 y = 0; y < ROOM_H; y++)
        for (u8 x = 0; x < ROOM_W; x++)
        {
            u8 t = room.tiles[y][x];
            u16 tile = t == TILE_SOLID ? GFX_TILE_SOLID : t == TILE_PLATFORM ? GFX_TILE_PLATFORM : 0;
            VDP_setTileMapXY(BG_B, TILE_ATTR_FULL(PAL0, 0, 0, 0, tile), x, y);
        }
}

static void drawPlayer(void)
{
    s16 px = player.x >> 8, py = player.y >> 8;
    u16 flip = player.facingLeft;
    u16 frame = player.crouching ? GFX_TILE_CROUCH : GFX_TILE_STAND;

    // Sprite 0: ninja (16 x 32, feet on row GFX_FEET_ROW of the art).
    VDP_setSpriteFull(0, px - 8, py - GFX_FEET_ROW - 1, SPRITE_SIZE(2, 4),
                      TILE_ATTR_FULL(PAL1, 1, 0, flip, frame), 1);

    // Sprite 1: slash in front of the chest, hidden off-screen when inactive.
    s16 sx = player.facingLeft ? px + 4 - 24 : px - 4;   // the arc starts 10 px into its art
    s16 sy = py - (player.crouching ? 16 : 24);
    if (!player_attackActive(&player)) sy = -64;
    VDP_setSpriteFull(1, sx, sy, SPRITE_SIZE(3, 2), TILE_ATTR_FULL(PAL1, 1, 0, flip, GFX_TILE_SLASH), 0);
    VDP_updateSprites(2, DMA_QUEUE);
}

#ifdef DEBUG_HUD
static void drawDebug(void)
{
    char line[41];
    VDP_setTextPalette(PAL0);
    sprintf(line, "X%4d Y%4d VX%5d VY%5d %c%c%c ", (s16) (player.x >> 8), (s16) (player.y >> 8),
            player.vx, player.vy, player.onGround ? 'G' : '-', player.crouching ? 'C' : '-',
            player_attackActive(&player) ? 'A' : '-');
    VDP_drawText(line, 1, 27);
}
#endif

static void enterRoom(void)
{
    mode = MODE_ROOM;
    VDP_clearPlane(BG_A, TRUE);
    drawRoom();
    VDP_setTextPalette(PAL0);
    VDP_drawText("START carte", 27, 0);
}

static void enterMap(void)
{
    mode = MODE_MAP;
    VDP_setSpritePosition(0, 0, -64);
    VDP_setSpritePosition(1, 0, -64);
    VDP_updateSprites(2, DMA_QUEUE);
    drawMap();
}

// ---------------------------------------------------------------- main

static u16 readPad(void)
{
#ifdef DEBUG_SCRIPT
    // Frame-exact replay of tools/script.h; the game freezes when the script ends.
    static u16 step = 0, frame = 0;
    if (step >= sizeof(SCRIPT) / sizeof(SCRIPT[0]))
    {
        VDP_drawText("FIN DU SCRIPT", 26, 26);
        while (TRUE) SYS_doVBlankProcess();
    }
    u16 pad = SCRIPT[step][1];
    if (++frame >= SCRIPT[step][0])
    {
        step++;
        frame = 0;
    }
    return pad;
#else
    return JOY_readJoypad(JOY_1);
#endif
}

int main(bool hardReset)
{
    (void) hardReset;
    gfx_load();
    VDP_resetSprites();
    player_setRegion(IS_PAL_SYSTEM);

    newFloor(0x1234);
    room_buildTest(&room);
    player_init(&player, 6 * 8, 25 * 8);
    enterRoom();

    u16 prevPad = 0;
    while (TRUE)
    {
        u16 pad = readPad();
        u16 pressed = pad & ~prevPad;
        prevPad = pad;

        if (mode == MODE_ROOM)
        {
            if (pressed & BUTTON_START) enterMap();
            else
            {
                player_update(&player, &room, pad);
                drawPlayer();
#ifdef DEBUG_HUD
                drawDebug();
#endif
            }
        }
        else
        {
            if (pressed & BUTTON_START) enterRoom();
            else updateMap(pressed);
        }
        SYS_doVBlankProcess();
    }
    return 0;
}
